-- Minced -- ingredient allergen tags and diet classes (wave 10c, generated; do not edit by hand)
--
-- Source of truth: scripts/allergens/review/tag-sources*.txt  ->  scripts/allergens/build.py --seed
-- Reviewed table with a reason per row: scripts/allergens/review/ingredient-allergens.csv
--
-- REPLACES the whole ingredient_allergens table (the old rows were partial and used one 'nuts' bucket) and sets
-- ingredients.diet_class for every ingredient, then rebuilds recipe_allergens and the derived recipe_diets.
-- Idempotent. Run after migration 202610181200xx, as the postgres role. Triggers are paused while the table is
-- rewritten and ONE bulk refresh runs at the end (per-row triggers would refresh every recipe thousands of times).

begin;

alter table ingredient_allergens disable trigger user;
alter table ingredients disable trigger user;

create temp table _tag (ingredient citext not null, allergen text not null, basis text not null, reason text not null) on commit drop;
create temp table _cls (ingredient citext primary key, diet_class text not null, reason text not null) on commit drop;



-- Reviewed diet exceptions (scripts/allergens/review/recipe-diet-exceptions.csv). The table is replaced as a whole.
delete from recipe_diet_exceptions;
select r.id, d.id, v.action, v.reason
from (values
  ('tostadas', 'vegetarian', 'add', 'The recipe lists its refried beans as fat-free, so they contain no lard; the ingredient default (refried beans = meat, because traditional ones use lard) does not apply.')
) as v (slug, diet, action, reason)
join recipes r on r.slug = v.slug
join diets d on d.slug = v.diet;
do $$ begin if (select count(*) from recipe_diet_exceptions) <> 1 then raise exception 'a diet exception names a recipe or diet that does not exist'; end if; end $$;

-- Fail loudly if a name or allergen slug does not resolve (a silently dropped tag is a false "safe").
do $$
declare bad text;
begin
  select string_agg(distinct t.ingredient::text, ', ') into bad from _tag t where not exists (select 1 from ingredients i where i.canonical_name = t.ingredient);
  if bad is not null then raise exception 'unknown ingredients in tag seed: %', bad; end if;
  select string_agg(distinct t.allergen, ', ') into bad from _tag t where not exists (select 1 from allergens a where a.slug = t.allergen);
  if bad is not null then raise exception 'unknown allergen slugs in tag seed (run migration 2026101812xxxx first): %', bad; end if;
  select string_agg(distinct c.ingredient::text, ', ') into bad from _cls c where not exists (select 1 from ingredients i where i.canonical_name = c.ingredient);
  if bad is not null then raise exception 'unknown ingredients in class seed: %', bad; end if;
  if (select count(*) from _cls) <> (select count(*) from ingredients) then
    raise exception 'class seed has % rows but there are % ingredients; regenerate it (build.py --seed)',
      (select count(*) from _cls), (select count(*) from ingredients);
  end if;
end $$;

delete from ingredient_allergens;
select i.id, a.id, t.basis, t.reason
from   _tag t
join   ingredients i on i.canonical_name = t.ingredient
join   allergens   a on a.slug = t.allergen
on conflict (ingredient_id, allergen_id) do update set basis = excluded.basis, reason = excluded.reason;

update ingredients i set diet_class = c.diet_class
from   _cls c
where  c.ingredient = i.canonical_name and i.diet_class is distinct from c.diet_class;

alter table ingredient_allergens enable trigger user;
alter table ingredients enable trigger user;

-- One bulk rebuild of the derived data (recipe_allergens with optional_only, and recipe_diets for catalog recipes).
select refresh_all_recipe_allergens();
select refresh_all_recipe_diets();

commit;
